<?php require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/pdf_generator.php';checkAuth(['economia','admin']);$db=getDBConnection();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['despacho'])){$iid=(int)$_POST['insumo_id'];$qty=numberValue($_POST['cantidad']??0);$s=$db->prepare('SELECT * FROM insumos WHERE id=? AND activo=1');$s->execute([$iid]);$i=$s->fetch();if($i&&$qty>0&&$qty<=$i['stock_actual']){$db->beginTransaction();$db->prepare('UPDATE insumos SET stock_actual=stock_actual-?,updated_at=? WHERE id=?')->execute([$qty,now(),$iid]);$db->prepare("INSERT INTO movimientos_almacen(insumo_id,tipo,cantidad,precio_unitario,concepto,fecha,usuario_id) VALUES(?,'despacho',?,?,?,?,?)")->execute([$iid,$qty,$i['precio_compra_unidad'],trim($_POST['concepto']),now(),$_SESSION['usuario']['id']]);$db->commit();$msg='Despacho registrado.';}else $msg='Cantidad inválida o stock insuficiente.';}elseif(isset($_POST['pdf'])){$date=$_POST['fecha'];$stock=$db->query('SELECT * FROM insumos WHERE activo=1 ORDER BY nombre')->fetchAll();$s=$db->prepare("SELECT m.*,i.nombre,i.unidad_medida FROM movimientos_almacen m JOIN insumos i ON i.id=m.insumo_id WHERE m.tipo='despacho' AND date(m.fecha)=? ORDER BY m.id");$s->execute([$date]);$out=$s->fetchAll();$sales=$db->prepare("SELECT COALESCE(SUM(monto_total_cup),0) FROM facturas WHERE tipo='comprobante' AND date(fecha)=?");$sales->execute([$date]);$total=(float)$sales->fetchColumn();$lines=['Fecha: '.$date,'','SALIDAS DEL DÍA'];foreach($out as $o)$lines[]=$o['nombre'].' · '.$o['cantidad'].' '.$o['unidad_medida'].' · '.money($o['cantidad']*$o['precio_unitario']);$lines[]='';$lines[]='EXISTENCIAS';foreach($stock as $x)$lines[]=$x['nombre'].' · '.$x['stock_actual'].' '.$x['unidad_medida'].' · valor '.money($x['stock_actual']*$x['precio_compra_unidad']);$lines[]='';$lines[]='DINERO ENTRANTE POR VENTAS: '.money((float)$total);$num=nextNumber('INV-');$path=generarDocumentoPDF('inventario',$num,'Reporte diario de inventario',$lines);$db->prepare("INSERT INTO facturas(numero,tipo,monto_total_cup,metodo_pago,pdf_path,fecha,usuario_id) VALUES(?,?,?,?,?,?,?)")->execute([$num,'inventario',0,'efectivo',$path,now(),$_SESSION['usuario']['id']]);$fid=(int)$db->lastInsertId();storeDocument('inventario',$fid,$num,$path);header('Location: '.url('economia/despachos.php?documento='.$fid));exit;}}$insumos=$db->query('SELECT * FROM insumos WHERE activo=1 AND stock_actual>0 ORDER BY nombre')->fetchAll();?><?php if(isset($_GET['documento'])): $docId=(int)$_GET['documento']; $ds=$db->prepare('SELECT numero FROM facturas WHERE id=?'); $ds->execute([$docId]); $doc=$ds->fetch(); if($doc): ?>
<div class="notice" style="margin-bottom:14px">Reporte <?=h($doc['numero'])?> generado. <button type="button" class="btn olive" id="openInvDoc">Abrir reporte</button></div>
<div id="invModal" class="doc-modal open"><div class="doc-modal-box"><div class="actions" style="justify-content:space-between;align-items:center"><strong>Reporte de inventario</strong><a class="btn gold" href="<?=url('admin/documentos.php?doc='.$docId.'&mode=download')?>">Descargar</a><button type="button" class="btn danger" id="closeInv">Cerrar</button></div><iframe src="<?=url('admin/documentos.php?doc='.$docId.'&mode=view')?>" title="Reporte"></iframe></div></div>
<style>.doc-modal{display:none;position:fixed;inset:0;background:rgba(0,0,0,.78);z-index:9999;padding:4vh 4vw}.doc-modal.open{display:block}.doc-modal-box{height:92vh;background:#fff;border-radius:14px;overflow:hidden;display:flex;flex-direction:column}.doc-modal-box .actions{padding:10px 14px;background:#1b1b1b;color:#fff}.doc-modal iframe{border:0;flex:1;width:100%;background:#fff}</style>
<script>document.getElementById('closeInv').onclick=function(){document.getElementById('invModal').classList.remove('open')};</script>
<?php endif; endif; ?>
<div class="card"><h1>Despacho diario</h1><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="despacho" value="1"><div><label>Insumo</label><select name="insumo_id"><?php foreach($insumos as $i):?><option value="<?=$i['id']?>"><?=h($i['nombre'])?> · <?=$i['stock_actual']?> <?=h($i['unidad_medida'])?></option><?php endforeach;?></select></div><div><label>Cantidad retirada</label><input type="number" step="0.01" name="cantidad" min="0.01" required></div><div class="full"><label>Concepto / destino</label><input name="concepto" placeholder="Producción, cocina, barra..."></div><div class="full"><button class="btn gold">Registrar salida</button></div></form></div><div class="card"><h2>Reporte PDF</h2><form method="post" class="actions"><input type="hidden" name="pdf" value="1"><input type="date" name="fecha" value="<?=date('Y-m-d')?>" required><button class="btn olive">Crear PDF de existencias + salidas + ventas</button></form></div><?php require_once __DIR__.'/../includes/footer.php';?>
